import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

max_diff = -1
best_X_Y = None

# Range for Y is 1 to 7976
# Range for X is 4049+Y to 12024+Y
# X must divide lcm(2024, Y)

for Y in range(1, 7977):
    L = lcm(2024, Y)

    # Instead of finding all divisors, we can just check if 
    # X - 2Y - 4048 could potentially be better than max_diff.
    # The max possible X is 12024+Y.
    # So the max potential diff is (12024+Y) - 2Y - 4048 = 7976 - Y.
    # If 7976 - Y <= max_diff, we can skip this Y.

    if 7976 - Y <= max_diff:
        continue

    # Find largest divisor of L in [4049+Y, 12024+Y]
    # Since L is at most 2019376, we can find divisors.
    divs = []
    for i in range(1, int(math.sqrt(L)) + 1):
        if L % i == 0:
            divs.append(i)
            if i*i != L:
                divs.append(L // i)
    divs.sort(reverse=True)

    for X in divs:
        if 4049 + Y <= X <= 12024 + Y:
            diff = X - 2*Y - 4048
            if diff > max_diff:
                max_diff = diff
                best_X_Y = (X, Y)
            break

print(f"Max diff: {max_diff}")
print(f"Best (X, Y): {best_X_Y}")

